#include "ringbuf.h"
#include <assert.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    /* --- basic create/destroy capacity/size/clear --- */
    {
        ringbuf_t *rb = rb_create(8);
        assert(rb != NULL);
        assert(rb_capacity(rb) == 8);
        assert(rb_size(rb) == 0);

        /* destroy NULL is allowed (no crash) */
        rb_destroy(NULL);

        /* clear on empty */
        rb_clear(rb);
        assert(rb_size(rb) == 0);

        rb_destroy(rb);
    }

    /* --- write / read roundtrip --- */
    {
        uint8_t data[] = {1, 2, 3, 4, 5};
        ringbuf_t *rb = rb_create(64);
        size_t w = rb_write(rb, data, sizeof(data));
        assert(w == 5);
        assert(rb_size(rb) == 5);

        uint8_t buf[10] = {0};
        size_t r = rb_read(rb, buf, sizeof(buf));
        assert(r == 5);
        assert(memcmp(buf, data, 5) == 0);
        assert(rb_size(rb) == 0);

        /* read from empty */
        assert(rb_read(rb, buf, 1) == 0);

        rb_destroy(rb);
    }

    /* --- NULL handling --- */
    {
        ringbuf_t *rb = rb_create(8);
        assert(rb_size(rb) == 0);
        assert(rb_read(rb, NULL, 1) == 0);
        assert(rb_write(rb, NULL, 1) == 0);
        assert(rb_capacity(rb) == 8);
        assert(rb_peek(rb, NULL, 1) == 0);

        /* invalid capacity */
        assert(rb_create(0) == NULL);
        rb_destroy(rb);
    }

    /* --- write half then read all then write rest --- */
    {
        ringbuf_t *rb = rb_create(4);

        uint8_t a[] = {1, 2};
        size_t w = rb_write(rb, a, 2);
        assert(w == 2);

        uint8_t b[4] = {0};
        size_t r = rb_read(rb, b, 2);
        assert(r == 2);
        assert(b[0] == 1 && b[1] == 2);

        /* now buffer is fully empty */
        uint8_t c[] = {3, 4};
        w = rb_write(rb, c, 2);
        assert(w == 2);
        r = rb_read(rb, b, 4);
        assert(r == 2 && b[0] == 3 && b[1] == 4);

        rb_destroy(rb);
    }

    /* --- write that exceeds free space --- */
    {
        ringbuf_t *rb = rb_create(8);

        uint8_t a[] = {1, 2};
        rb_write(rb, a, 2);          /* filled 2 bytes                    */

        /* try to write 16 → should write 6 and return 6               */
        uint8_t tmp[32];
        memset(tmp, 'A', sizeof(tmp));
        size_t w = rb_write(rb, tmp, 32);
        assert(w == 6);                 /* only 6 bytes fit                   */
        assert(rb_size(rb) == 8);

        uint8_t out[16] = {0};
        size_t r = rb_read(rb, out, 16);
        assert(r == 8);
        assert(out[0] == 1 && out[1] == 2);  /* oldest first     */
        for (int i = 2; i < 8; i++)
            assert(out[i] == 'A');

        rb_destroy(rb);
    }

    /* --- wrap-around of internal storage --- */
    {
        ringbuf_t *rb = rb_create(4);

        /* fill partially, read back, fill again to drive indices past end*/
        uint8_t a[] = {10, 20};
        assert(rb_write(rb, a, 2) == 2);

        uint8_t out[4] = {0};
        assert(rb_read(rb, out, 2) == 2);   /* consume everything */

        /* now write 4 bytes → indices wrap                        */
        uint8_t b[] = {1, 2, 3, 4};
        assert(rb_write(rb, b, 4) == 4);
        assert(rb_size(rb) == 4);

        uint8_t out2[4] = {0};
        assert(rb_read(rb, out2, 4) == 4);
        for (int i = 0; i < 4; i++)
            assert(out2[i] == 1 + i);

        rb_destroy(rb);
    }

    /* --- peek does not consume data --- */
    {
        ringbuf_t *rb = rb_create(8);
        uint8_t a[] = {5, 6, 7};
        rb_write(rb, a, 3);

        uint8_t p[3] = {0};
        assert(rb_peek(rb, p, 3) == 3);
        assert(p[0] == 5 && p[1] == 6 && p[2] == 7);
        assert(rb_size(rb) == 3);      /* peek must not reduce size */

        rb_destroy(rb);
    }

    printf("All tests passed.\n");
    return 0;
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

typedef struct ringbuf {
    uint8_t *storage;
    size_t capacity;       /* fixed capacity of storage                */
    size_t head;           /* next write index                         */
    size_t tail;           /* next read index                          */
    size_t count;          /* bytes currently stored (0..capacity)     */
} ringbuf_t;

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    uint8_t *storage = malloc(capacity);
    if (!storage)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb) {
        free(storage);
        return NULL;
    }

    rb->storage   = storage;
    rb->capacity  = capacity;
    rb->head      = 0;
    rb->tail      = 0;
    rb->count     = 0;

    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;

    free(rb->storage);
    free(rb);
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;

    rb->head  = 0;
    rb->tail  = 0;
    rb->count = 0;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    if (len > rb->capacity - rb->count) {
        /* truncate to fit */
        len = rb->capacity - rb->count;
        assert(len <= rb->storage ? len : 0);
    }
    assert(data && len == 0 || data);  /* data valid or len==0 caught above */

    for (size_t i = 0; i < len; i++)
        rb->storage[(rb->head + i) % rb->capacity] = data[i];

    rb->head = (rb->head + len) % rb->capacity;
    rb->count += len;

    return len;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || rb->count == 0 || len == 0)
        return 0;

    if (len > rb->count)
        len = rb->count;

    for (size_t i = 0; i < len; i++)
        out[i] = rb->storage[(rb->tail + i) % rb->capacity];

    rb->tail = (rb->tail + len) % rb->capacity;
    rb->count -= len;

    return len;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || rb->count == 0 || len == 0)
        return 0;

    if (len > rb->count)
        len = rb->count;

    for (size_t i = 0; i < len; i++)
        out[i] = rb->storage[(rb->tail + i) % rb->capacity];

    /* count unchanged — this is peek, not read */
    return len;
}

